<?php use FilamentManager\Core\View; ?>
<h1><?= View::t('users') ?></h1><div class="grid"><section class="card"><h2><?= View::t('new_user') ?></h2><form method="post" action="<?= View::e($basePath) ?>/admin/users"><?= View::csrf() ?><label><?= View::t('username') ?><input name="username" required></label><label><?= View::t('display_name') ?><input name="display_name"></label><label><?= View::t('email') ?><input name="email" type="email"></label><label><?= View::t('password') ?><input name="password" type="password" minlength="12" required autocomplete="new-password"></label><label><?= View::t('role') ?><select name="role"><option value="viewer">Viewer</option><option value="operator">Operator</option><option value="manager">Manager</option><option value="admin">Admin</option></select></label><label><?= View::t('language') ?><select name="locale"><option value="cs">Čeština</option><option value="en">English</option></select></label><button><?= View::t('save') ?></button></form></section><section><div class="table-wrap"><table><thead><tr><th><?= View::t('username') ?></th><th><?= View::t('role') ?></th><th><?= View::t('status') ?></th><th><?= View::t('last_login') ?></th><th></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= View::e($u['display_name']) ?></strong><br><small><?= View::e($u['username']) ?></small></td><td><?= View::e($u['role']) ?></td><td><?= $u['is_active']?View::t('active'):View::t('disabled') ?></td><td><?= View::e($u['last_login_at']??'—') ?></td><td><?php if($u['id']!==$app->auth()->user()['id']): ?><div class="actions"><form method="post" action="<?= View::e($basePath) ?>/admin/users/<?= View::e($u['id']) ?>/toggle"><?= View::csrf() ?><button class="secondary-button small-button"><?= $u['is_active']?View::t('disable'):View::t('enable') ?></button></form><form method="post" action="<?= View::e($basePath) ?>/admin/users/<?= View::e($u['id']) ?>/delete"><?= View::csrf() ?><button class="danger-button small-button"><?= View::t('delete') ?></button></form></div><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></div>
